def _prefit(self, items, cfg: Optional[GateConfig] = None) -> None:
    """Fit concurrently (cached, failures remembered) so sequential admission reads finished fits."""
    cfg = cfg or self.gate_cfg

    def one(item) -> None:
        path, name = item
        if path.name == "candidate.py" and read_candidate(path.parent) is not None:
            return
        if code_problems(path.read_text(encoding="utf-8")):
            return
        try:
            self._fit(path, name, cfg)
        except ModelFailure:
            pass  # remembered; admission reports it
        except Exception:
            if path.name == "candidate.py":
                return  # a file the gates will refuse (not a theory, a memo error): admission says why
            raise

    if not items:
        return
    workers = 1 if cfg.time_limit_sec is None else min(len(items), self.cfg.fit_workers or default_fit_workers())
    with ThreadPoolExecutor(max_workers=workers) as pool:
        list(pool.map(one, items))

# ---------- bookkeeping ----------
def _ledger(self, name: str, outcome: str, detail: str, hypothesis: str, context: str) -> None:
    self.ledger.append(LedgerEntry(name=name, outcome=outcome, detail=detail,
                                   hypothesis=collapse_whitespace(hypothesis), context=context))

def _write_manifest(self) -> None:
    entries = [dict(name=m.name, rationale=collapse_whitespace(m.hypothesis)) for m in self.live.values()]
    (self.models_dir / "models_manifest.yaml").write_text(yaml.safe_dump({"models": entries}, sort_keys=False))

def _reserved(self) -> set:
    return set(self.live) | {e.name for e in self.ledger.entries()}

REFIT_TARGET_ACCEPT = 0.95


def refit_settings(settings: FitSettings) -> FitSettings:
    """The one refit of a fit that fails the convergence gate: target_accept
    0.95 and a seed of its own."""
    return replace(settings, target_accept=max(settings.target_accept, REFIT_TARGET_ACCEPT), seed=settings.seed + 1)


def loop_fit(model_path: Path, name: str, responses_path: Path, settings: FitSettings, cache_dir: Path,
             *, time_limit_sec: Optional[float] = None) -> RSAFit:
    """The fit the loop uses for a model: the fit at ``settings``, or, when it
    fails the convergence gate, the refit (`refit_settings`). Everything that
    scores the loop's models (admission, held-out, recovery) goes through
    this, so all of them read the same cached fit."""
    fitted = fit_cached(model_path, name, responses_path, settings, cache_dir, time_limit_sec=time_limit_sec)
    if fitted.converged:
        return fitted
    return fit_cached(model_path, name, responses_path, refit_settings(settings), cache_dir,
                      time_limit_sec=time_limit_sec)


def cached_fits(cache_dir: Path) -> List[Path]:
    return sorted(Path(cache_dir).glob("*.nc"))


def describe(fitted: RSAFit) -> dict[str, Any]:
    return dict(name=fitted.model_name, converged=fitted.converged, problems=fitted.convergence_problems)

